      const numeric=value=>{const parsed=typeof value==='number'?value:Number(String(value??'').replaceAll(',',''));if(!Number.isFinite(parsed))throw new Error(`“${value}” ไม่ใช่ตัวเลข`);return parsed;};
      const clean=value=>typeof value==='number'&&Number.isFinite(value)?Number(value.toFixed(10)):value;
