  function markerStyle(type,index) {const label=String(type||'อ').trim(),hash=[...label].reduce((sum,char)=>sum+char.codePointAt(0),0);return {color:markerPalette[hash%markerPalette.length],glyph:label.slice(0,1).toUpperCase()||String(index+1)};}
