  function siteMapPanel(site,equipment) {const types=[...new Set(equipment.map(item=>item.type))],link=directionsUrl(site);return `<section class="report-site-map"><header><div><span>ตำแหน่งไซต์และอุปกรณ์</span><strong>${hasCoordinates(site)?`${Number(site.latitude).toFixed(6)}, ${Number(site.longitude).toFixed(6)}`:'ยังไม่ระบุพิกัด · จะแสดง My Location'}</strong></div>${link?`<a href="${link}" target="_blank" rel="noopener">นำทางไปไซต์ ↗</a>`:''}</header><div id="report-site-map" class="report-site-map__canvas"><div class="report-map-placeholder"><strong>กำลังเตรียมภาพดาวเทียม…</strong><small>${hasCoordinates(site)?'อุปกรณ์พิกัดเดียวกันจะถูกรวมเป็นกลุ่ม':'ระบบจะขอใช้ My Location หากยังไม่มีพิกัด'}</small></div></div>${types.length?`<div class="report-map-legend">${types.map((type,index)=>{const style=markerStyle(type,index);return `<span><i style="--pin-color:${style.color}">${esc(style.glyph)}</i>${esc(type)}</span>`;}).join('')}</div>`:''}</section>`;}
