    bindFieldConfigDialog(dialog);dialog.querySelectorAll('button[value="cancel"]').forEach(button=>{button.type='button';button.addEventListener('click',()=>dialog.close());});dialog.addEventListener('close',()=>{host.innerHTML='';state.uploadDraft=null;state.formulaBuilder=null;});dialog.showModal();return dialog;
