  function pageManager(template,scope) {
    normalizeTemplatePages(template);return `<section class="template-page-manager"><header><div><span>แบ่งหน้าฟอร์ม</span><strong>ระบบกำหนดเลขหน้าให้อัตโนมัติ</strong></div><button type="button" class="module-secondary" data-page-add="${scope}">＋ เพิ่มหน้า</button></header><div class="template-page-list">${template.pages.map(page=>`<div class="template-page-item"><span>${page.number}</span><label>ชื่อหน้า<input data-page-title="${scope}" data-page-number="${page.number}" value="${esc(page.title)}" placeholder="เช่น ข้อมูลการติดตั้ง"></label>${template.pages.length>1?`<button type="button" class="danger-link" data-page-delete="${scope}" data-page-number="${page.number}" aria-label="ลบหน้า ${page.number}">ลบ</button>`:''}</div>`).join('')}</div></section>`;
  }
