    sites:{label:'ไซต์งาน',headers:['work_group_id','site_id','site_name','description','map_pin_text','moo','village','subdistrict','district','province','latitude','longitude'],sample:[['FY2569','SITE-D','ไซต์ D โรงงานระยอง','งานติดตั้งปี 2569','SITE-D · ระยอง','4','บ้านตัวอย่าง','มาบตาพุด','เมืองระยอง','ระยอง','12.681395','101.281626']]},
    equipment:{label:'อุปกรณ์',headers:['work_group_id','site_id','equipment_id','equipment_type','equipment_name','model','serial_number','location','latitude','longitude'],sample:[['FY2569','SITE-A','SM4','Soil Moisture Sensor','Soil Moisture Sensor','SM-100','SMS-2026-004','Zone D','13.499100','100.994200']]},
