  function csvDialog(entity) { const spec=csvSpecs[entity];showDialog(`<form data-csv-form="${entity}" class="wh-form"><div class="wh-dialog__head"><div><span>BULK IMPORT</span><h4>นำเข้า${spec.label}จาก CSV</h4></div><button value="cancel">×</button></div><div class="csv-header-list">${spec.headers.map(item=>`<code>${item}</code>`).join('')}</div><button type="button" class="module-secondary" data-csv-download="${entity}">ดาวน์โหลด CSV Template</button><label class="report-dropzone">ไฟล์ CSV<input name="file" type="file" accept=".csv,text/csv" required><span>เลือกไฟล์ CSV ที่ต้องการนำเข้า</span><small>รองรับ UTF-8 และตรวจข้อมูลซ้ำก่อนบันทึก</small></label><fieldset class="csv-policy"><legend>เมื่อพบข้อมูลเดิม</legend><label><input type="radio" name="policy" value="blank" checked> กรอกเฉพาะช่องว่าง</label><label><input type="radio" name="policy" value="overwrite"> ทับข้อมูลเดิม</label><label><input type="radio" name="policy" value="skip"> ข้ามรายการ</label></fieldset><div class="wh-form__actions"><button value="cancel" class="module-secondary">ยกเลิก</button><button type="submit" class="module-primary">ตรวจสอบและนำเข้า</button></div></form>`,'report-csv-dialog'); }

  function parseCsv(text) {const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const char=text[i],next=text[i+1];if(char==='"'&&quote&&next==='"'){cell+='"';i++;}else if(char==='"')quote=!quote;else if(char===','&&!quote){row.push(cell);cell='';}else if((char==='\n'||char==='\r')&&!quote){if(char==='\r'&&next==='\n')i++;row.push(cell);if(row.some(value=>value.trim()))rows.push(row);row=[];cell='';}else cell+=char;}row.push(cell);if(row.some(value=>value.trim()))rows.push(row);if(!rows.length)return[];const headers=rows.shift().map(item=>item.trim().replace(/^\uFEFF/,'').toLowerCase());return rows.map(values=>Object.fromEntries(headers.map((header,index)=>[header,(values[index]||'').trim()])));}
  function csvText(headers,rows){const quote=value=>`"${String(value??'').replaceAll('"','""')}"`;return [headers.map(quote).join(','),...rows.map(row=>row.map(quote).join(','))].join('\r\n');}
  function download(name,blob){const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

  async function importCsv(entity,file,policy) {
    const rows=parseCsv(await file.text());if(!rows.length)throw new Error('ไม่พบข้อมูลใน CSV');let created=0,updated=0,conflicts=[];
    const merge=(target,source,fields)=>{fields.forEach(field=>{const incoming=source[field];if(incoming==='')return;if(target[field]&&String(target[field])!==incoming)conflicts.push(field);if(policy==='overwrite'||!target[field])target[field]=incoming;});};
    if(entity==='groups')for(const row of rows){let item=state.data.groups.find(g=>g.code===row.work_group_id),shortCode=threeCharacters(row.short_code||String(row.fiscal_year||row.work_group_id).slice(-3));if(!item){item={id:uid('wg'),code:row.work_group_id,name:row.work_group_name,fiscalYear:row.fiscal_year,shortCode};state.data.groups.push(item);created++;}else if(policy!=='skip'){merge(item,{name:row.work_group_name,fiscalYear:row.fiscal_year,shortCode},['name','fiscalYear','shortCode']);updated++;}}
    if(entity==='sites')for(const row of rows){const group=state.data.groups.find(g=>g.code===row.work_group_id);if(!group){conflicts.push(`ไม่พบกลุ่ม ${row.work_group_id}`);continue;}const coords=coordinatesFromRow(row);if((row.latitude||row.lat||row.n||row.longitude||row.lng||row.long||row.e)&&(!hasCoordinates(coords)))conflicts.push(`${row.site_id}: พิกัดไม่ถูกต้อง`);const source={name:row.site_name,description:row.description||row.customer,mapPinText:row.map_pin_text,moo:row.moo,village:row.village,subdistrict:row.subdistrict,district:row.district,province:row.province||provinceFromAddress(row.address),address:row.address,...coords};let item=state.data.sites.find(s=>s.groupId===group.id&&s.id===row.site_id);if(!item){item={uid:uid('site'),id:row.site_id,groupId:group.id,...source};item.address=siteAddress(item);state.data.sites.push(item);created++;}else if(policy!=='skip'){merge(item,source,['name','description','mapPinText','moo','village','subdistrict','district','province','address','latitude','longitude']);item.address=siteAddress(item);updated++;}}
    if(entity==='equipment')for(const row of rows){const group=state.data.groups.find(g=>g.code===row.work_group_id),site=state.data.sites.find(s=>s.groupId===group?.id&&s.id===row.site_id);if(!group||!site){conflicts.push(`ไม่พบ ${row.work_group_id}/${row.site_id}`);continue;}const coords=coordinatesFromRow(row);let item=state.data.equipment.find(e=>e.siteId===site.uid&&e.id===row.equipment_id);if(!item){state.data.equipment.push({uid:uid('eq'),id:row.equipment_id,groupId:group.id,siteId:site.uid,type:row.equipment_type,name:row.equipment_name||row.equipment_type,model:row.model,serial:row.serial_number,location:row.location,...coords});created++;}else if(policy!=='skip'){merge(item,{type:row.equipment_type,name:row.equipment_name,model:row.model,serial:row.serial_number,location:row.location,...coords},['type','name','model','serial','location','latitude','longitude']);updated++;}}
    save();return {created,updated,conflicts};
  }

