  function bulkWorkbookDialog(){showDialog(`<form data-bulk-xlsx-form class="wh-form"><div class="wh-dialog__head"><div><span>ONE-FILE IMPORT</span><h4>นำเข้ากลุ่ม ไซต์ และอุปกรณ์ทั้งชุด</h4></div><button value="cancel">×</button></div><div class="bulk-sheet-map"><span><strong>1</strong> Groups</span><i>→</i><span><strong>2</strong> Sites</span><i>→</i><span><strong>3</strong> Equipment</span></div><p class="form-note">ระบบอ้างอิง <code>work_group_id</code> และ <code>site_id</code> จึงเพิ่มหลายไซต์และอุปกรณ์หลาย ID ได้ในครั้งเดียว</p><button type="button" class="module-secondary" data-bulk-xlsx-download>ดาวน์โหลด XLSX Template ตัวอย่าง</button><label class="report-dropzone">ไฟล์ XLSX<input name="file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required><span>เลือก Workbook ที่มี Sheet Groups, Sites และ Equipment</span><small>ระบบจะตรวจลำดับความสัมพันธ์ก่อนบันทึก</small></label><fieldset class="csv-policy"><legend>เมื่อพบข้อมูลเดิม</legend><label><input type="radio" name="policy" value="blank" checked> กรอกเฉพาะช่องว่าง</label><label><input type="radio" name="policy" value="overwrite"> ทับข้อมูลเดิม</label><label><input type="radio" name="policy" value="skip"> ข้ามรายการ</label></fieldset><div class="wh-form__actions"><button value="cancel" class="module-secondary">ยกเลิก</button><button type="submit" class="module-primary">ตรวจสอบและนำเข้าทั้งชุด</button></div></form>`,'report-bulk-dialog');}
  async function importBulkWorkbook(file,policy){if(!file)throw new Error('กรุณาเลือกไฟล์ XLSX');const sheets=await window.WorkHubReportXlsx.parseWorkbook(file),find=name=>Object.entries(sheets).find(([key])=>key.toLowerCase()===name.toLowerCase())?.[1]||[],required=['Groups','Sites','Equipment'];for(const name of required)if(!find(name).length)throw new Error(`ไม่พบข้อมูลใน Sheet ${name}`);let total={created:0,updated:0,conflicts:[]};for(const [entity,sheet] of [['groups','Groups'],['sites','Sites'],['equipment','Equipment']]){const rows=find(sheet),blob=new Blob([csvText(Object.keys(rows[0]),rows.map(row=>Object.keys(rows[0]).map(key=>row[key]??'')))],{type:'text/csv'}),result=await importCsv(entity,blob,policy);total.created+=result.created;total.updated+=result.updated;total.conflicts.push(...result.conflicts.map(item=>`${sheet}: ${item}`));}return total;}

  function templateFieldsDialog() {const template=selectedTemplate();normalizeTemplatePages(template);showDialog(`<form data-template-fields-form="${esc(template.id)}" class="wh-form"><div class="wh-dialog__head"><div><span>${esc(template.name)}</span><h4>ตั้งค่าหน้า Fields และสูตรคำนวณ</h4></div><button value="cancel">×</button></div>${pageManager(template,'template')}<p class="field-order-help">เลือกชื่อหน้าให้แต่ละ Field ได้โดยไม่ต้องพิมพ์เลข ลาก ⋮⋮ เพื่อเรียงแบบซ้าย → ขวา หรือใช้ ↑ ↓ บนโทรศัพท์</p><div class="wizard-field-list">${fieldEditorRows(template.fields,'template',template.pages)}</div><div class="add-custom-inline"><input name="newKey" placeholder="field_key"><input name="newLabel" placeholder="ชื่อ Field เพิ่มเติม"><select name="newType"><option value="text">ข้อความ</option><option value="number">ตัวเลข</option><option value="formula">สูตรคำนวณ</option></select><button type="submit" class="module-secondary" name="intent" value="add-field">＋ เพิ่ม Field</button></div>${formulaBuilderPanel(template,'template')}<p class="form-note">Field จาก Template ใช้แทน Placeholder ส่วน Field เพิ่มเติมเลือกเป็นสูตรคำนวณได้และจะอัปเดตผลลัพธ์อัตโนมัติ</p><div class="wh-form__actions"><button value="cancel" class="module-secondary">ยกเลิก</button><button type="submit" class="module-primary" name="intent" value="save">บันทึก Fields</button></div></form>`,'report-fields-dialog');}

  const reportCsvSystemHeaders=['site_id','equipment_id','equipment_type','equipment_name'];
  function reportCsvScope(template,groupId='',type='') {return state.data.equipment.filter(item=>(!groupId||item.groupId===groupId)&&(!type||item.type===type)&&templateForEquipment(item)?.id===template.id);}
  function reportCsvRows(template,groupId='',type='') {const fields=template.fields.filter(field=>field.type!=='image'&&field.type!=='formula');return reportCsvScope(template,groupId,type).map(item=>{const site=state.data.sites.find(row=>row.uid===item.siteId),values=ensureReport(item).values;return [site?.id||'',item.id,item.type,item.name,...fields.map(field=>values[field.key]??'')];});}
  function reportCsvDialog(templateId,{groupId='',type=''}={}) {
    const template=state.data.templates.find(item=>item.id===templateId)||selectedTemplate();if(!template)return alert('ไม่พบ Template ที่เลือก');state.selectedTemplate=template.id;const fields=template.fields.filter(field=>field.type!=='image'&&field.type!=='formula'),headers=[...reportCsvSystemHeaders,...fields.map(field=>field.key)],scope=reportCsvScope(template,groupId,type);showDialog(`<form data-report-csv-form="${esc(template.id)}" data-report-csv-group="${esc(groupId)}" data-report-csv-type="${esc(type)}" class="wh-form"><div class="wh-dialog__head"><div><span>CSV · ${esc(template.name)}</span><h4>กรอกข้อมูลอุปกรณ์หลายรายการ</h4></div><button value="cancel">×</button></div><p class="form-note">ระบบเตรียม Site ID, Equipment ID, ประเภท และชื่ออุปกรณ์ไว้ให้แล้ว ${scope.length} รายการ กรอกเฉพาะช่องข้อมูลรายงาน ส่วนรูปภาพให้อัปโหลดในหน้าอุปกรณ์ และ Field สูตรจะคำนวณอัตโนมัติ</p><div class="csv-header-list">${headers.map(item=>`<code>${esc(item)}</code>`).join('')}</div><button type="button" class="module-secondary" data-report-csv-download="${esc(template.id)}" data-report-csv-group="${esc(groupId)}" data-report-csv-type="${esc(type)}">ดาวน์โหลด CSV Template (${scope.length} อุปกรณ์)</button><label class="report-dropzone">ไฟล์ CSV<input name="file" type="file" accept=".csv,text/csv" required><span>เลือก CSV ที่กรอกข้อมูลแล้ว</span></label><fieldset class="csv-policy"><legend>ถ้าช่องนั้นมีข้อมูลอยู่แล้ว</legend><label><input type="radio" name="policy" value="blank" checked> กรอกเฉพาะช่องว่าง</label><label><input type="radio" name="policy" value="overwrite"> ทับข้อมูลเดิมด้วย CSV</label></fieldset><div class="wh-form__actions"><button value="cancel" class="module-secondary">ยกเลิก</button><button type="submit" class="module-primary">ตรวจสอบและนำเข้า</button></div></form>`,'report-csv-dialog');
  }
  async function importReportCsv(templateId,file,policy,groupId='',type='') {const template=state.data.templates.find(t=>t.id===templateId);if(!template)throw new Error('ไม่พบ Template ที่เลือก');const rows=parseCsv(await file.text());let updated=0,conflicts=[];for(const row of rows){const candidateSites=state.data.sites.filter(s=>s.id===row.site_id&&(!groupId||s.groupId===groupId)),equipment=state.data.equipment.find(e=>candidateSites.some(site=>site.uid===e.siteId)&&e.id===row.equipment_id&&(!type||e.type===type));if(!equipment||templateForEquipment(equipment)?.id!==template.id){conflicts.push(`${row.site_id}/${row.equipment_id}: ไม่พบอุปกรณ์หรือใช้ Template อื่น`);continue;}const report=ensureReport(equipment);for(const field of template.fields.filter(f=>f.type!=='image'&&f.type!=='formula')){const incoming=row[field.key];if(incoming==null||incoming==='')continue;if(report.values[field.key]&&report.values[field.key]!==incoming)conflicts.push(`${row.site_id}/${row.equipment_id} · ${field.key}`);if(policy==='blank'&&report.values[field.key])continue;report.values[field.key]=incoming;}report.values=calculateFormulaFields(template,report.values);report.updatedAt=nowText();updated++;}save();return{updated,conflicts};}

