    eventRoot.addEventListener('input',event=>{if(event.target.matches('[data-report-global-search]')){state.globalSearch=event.target.value;clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>{render();requestAnimationFrame(()=>{const input=root().querySelector('[data-report-global-search]');if(input){input.focus();input.setSelectionRange(input.value.length,input.value.length);}});},180);return;}if(event.target.matches('[data-report-search]')){state.search=event.target.value;renderTemplates();}if(event.target.matches('[data-template-label]')){const template=selectedTemplate();if(template)template.fields[Number(event.target.dataset.templateLabel)].label=event.target.value;}if(event.target.matches('[data-formula-expression]')){state.formulaBuilder.expression=event.target.value;const template=state.formulaBuilder.scope==='draft'?state.uploadDraft:selectedTemplate(),panel=event.target.closest('.formula-builder'),fieldValues=Object.fromEntries(template.fields.filter(field=>field.key!==state.formulaBuilder.key).map(field=>[field.key,field.type==='text'||field.type==='textarea'?'ตัวอย่าง':10])),result=evaluateFormula(event.target.value,fieldValues),preview=panel?.querySelector('.formula-preview');if(preview){preview.classList.toggle('has-error',!!result.error);preview.querySelector('span').textContent=result.error?'ตรวจสูตร':'ตัวอย่างผลลัพธ์';preview.querySelector('strong').textContent=result.error||String(result.value);panel.querySelector('[data-formula-apply]').disabled=!!result.error;}}const reportForm=event.target.closest?.('[data-report-data-form]');if(reportForm&&!event.target.matches('[data-formula-output]'))refreshFormulaOutputs(reportForm);});
    eventRoot.addEventListener('dragstart',event=>{const daily=event.target.closest?.('[data-daily-detail-row]');if(daily){state.dailyDraggedDetail=daily.dataset.dailyDetailRow;daily.classList.add('is-dragging');if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',state.dailyDraggedDetail);}return;}const handle=event.target.closest?.('[data-field-drag]');if(!handle)return;state.draggedField={scope:handle.dataset.fieldDrag,index:Number(handle.dataset.fieldIndex)};handle.closest('.wizard-field-row')?.classList.add('is-dragging');if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',`${state.draggedField.scope}:${state.draggedField.index}`);}});
    eventRoot.addEventListener('dragover',event=>{const daily=event.target.closest?.('[data-daily-detail-row]');if(daily&&state.dailyDraggedDetail){event.preventDefault();daily.classList.add('is-drag-target');return;}const row=event.target.closest?.('[data-field-drop]');if(!row||!state.draggedField||row.dataset.fieldDrop!==state.draggedField.scope)return;event.preventDefault();if(event.dataTransfer)event.dataTransfer.dropEffect='move';row.classList.add('is-drag-target');});
