    eventRoot.addEventListener('drop',event=>{const daily=event.target.closest?.('[data-daily-detail-row]');if(daily&&state.dailyDraggedDetail){event.preventDefault();const report=syncDailyForm(),from=report.details.findIndex(item=>item.id===state.dailyDraggedDetail),to=report.details.findIndex(item=>item.id===daily.dataset.dailyDetailRow);moveField(report.details,from,to);state.dailyDraggedDetail=null;renderDailyReports();return;}const row=event.target.closest?.('[data-field-drop]'),drag=state.draggedField;if(!row||!drag||row.dataset.fieldDrop!==drag.scope)return;event.preventDefault();const target=Number(row.dataset.fieldIndex);syncFieldConfigInputs(row.closest('.template-wizard,form'),drag.scope);if(drag.scope==='draft'){if(moveField(state.uploadDraft.fields,drag.index,target))renderTemplateWizard();}else if(moveField(selectedTemplate().fields,drag.index,target))templateFieldsDialog();state.draggedField=null;});
    eventRoot.addEventListener('dragend',()=>{state.draggedField=null;state.dailyDraggedDetail=null;eventRoot.querySelectorAll('.is-dragging,.is-drag-target').forEach(node=>node.classList.remove('is-dragging','is-drag-target'));});
