      if(event.target.matches('[data-group-select]')){state.selectedGroup=event.target.value;state.selectedSite=state.data.sites.find(s=>s.groupId===state.selectedGroup)?.uid||'';state.selectedProvinces.clear();state.provinceFilterExplicit=false;state.provinceFilterOpen=false;state.hideCompletedSites=false;render();return;}
