      if(event.target.matches('[data-province-filter]')){const province=event.target.dataset.provinceFilter,all=[...new Set(state.data.sites.filter(site=>site.groupId===state.selectedGroup).map(site=>site.province||provinceFromAddress(site.address)))];if(!state.provinceFilterExplicit)all.forEach(item=>state.selectedProvinces.add(item));state.provinceFilterExplicit=true;state.provinceFilterOpen=true;event.target.checked?state.selectedProvinces.add(province):state.selectedProvinces.delete(province);renderReportSites();return;}
