      if(event.target.closest('[data-daily-export]'))return exportDailyReport();
      const dailyQty=event.target.closest('[data-daily-qty]');if(dailyQty){const report=syncDailyForm(),scope=dailyQty.dataset.dailyScope,key=dailyQty.dataset.dailyKey;report[scope][key].qty=Math.max(0,Number(report[scope][key].qty||0)+Number(dailyQty.dataset.dailyQty));renderDailyReports();return;}
