      const go=event.target.closest('[data-report-go]');if(go){state.active=go.dataset.reportGo;if(state.active==='reports')state.reportStep='groups';render();return;}
      const step=event.target.closest('[data-report-step]');if(step){state.reportStep=step.dataset.reportStep;renderReports();return;}
      const favoriteGroup=event.target.closest('[data-favorite-group]');if(favoriteGroup){const id=favoriteGroup.dataset.favoriteGroup;state.data.favorites.groupId=state.data.favorites.groupId===id?'':id;persist(state.data.favorites.groupId?'ตั้งเป็นกลุ่มงานโปรดแล้ว':'ยกเลิกกลุ่มงานโปรดแล้ว');return;}
      const favoriteSite=event.target.closest('[data-favorite-site]');if(favoriteSite){const id=favoriteSite.dataset.favoriteSite,index=state.data.favorites.siteIds.indexOf(id);index>=0?state.data.favorites.siteIds.splice(index,1):state.data.favorites.siteIds.unshift(id);persist(index>=0?'ยกเลิกไซต์โปรดแล้ว':'เพิ่มไซต์โปรดแล้ว');return;}
      const groupOpen=event.target.closest('[data-report-group-open]');if(groupOpen){state.selectedGroup=groupOpen.dataset.reportGroupOpen;state.selectedSite='';state.selectedEquipment='';state.selectedProvinces.clear();state.provinceFilterExplicit=false;state.provinceFilterOpen=false;state.hideCompletedSites=false;state.reportStep='sites';renderReports();return;}
