      const pageAdd=event.target.closest('[data-page-add]');if(pageAdd){const scope=pageAdd.dataset.pageAdd,container=pageAdd.closest('.template-wizard,form'),template=scope==='draft'?state.uploadDraft:selectedTemplate();syncFieldConfigInputs(container,scope);addTemplatePage(template);scope==='draft'?renderTemplateWizard():templateFieldsDialog();return;}
      const pageDelete=event.target.closest('[data-page-delete]');if(pageDelete){const scope=pageDelete.dataset.pageDelete,container=pageDelete.closest('.template-wizard,form'),template=scope==='draft'?state.uploadDraft:selectedTemplate();syncFieldConfigInputs(container,scope);removeTemplatePage(template,Number(pageDelete.dataset.pageNumber));scope==='draft'?renderTemplateWizard():templateFieldsDialog();return;}
      const formulaEdit=event.target.closest('[data-formula-edit]');if(formulaEdit){const scope=formulaEdit.dataset.formulaScope,container=formulaEdit.closest('.template-wizard,form'),template=scope==='draft'?state.uploadDraft:selectedTemplate();syncFieldConfigInputs(container,scope);const field=template.fields.find(item=>item.key===formulaEdit.dataset.formulaEdit);if(field){field.type='formula';state.formulaBuilder={scope,key:field.key,expression:field.formula||''};scope==='draft'?renderTemplateWizard():templateFieldsDialog();}return;}
      const formulaToken=event.target.closest('[data-formula-token]');if(formulaToken){const textarea=formulaToken.closest('.formula-builder')?.querySelector('[data-formula-expression]');if(!textarea)return;const token=formulaToken.dataset.formulaToken,start=textarea.selectionStart??textarea.value.length,end=textarea.selectionEnd??start,isFunction=token.endsWith('()'),insertion=token;textarea.setRangeText(insertion,start,end,'end');if(isFunction)textarea.setSelectionRange(start+token.length-1,start+token.length-1);textarea.dispatchEvent(new Event('input',{bubbles:true}));textarea.focus();return;}
