      if(event.target.closest('[data-formula-apply]')){const builder=state.formulaBuilder;if(!builder)return;syncFieldConfigInputs(event.target.closest('.template-wizard,form'),builder.scope);const template=builder.scope==='draft'?state.uploadDraft:selectedTemplate(),field=template.fields.find(item=>item.key===builder.key),result=evaluateFormula(builder.expression,Object.fromEntries(template.fields.map(item=>[item.key,10])));if(result.error)return alert(result.error);field.type='formula';field.formula=builder.expression.trim();state.formulaBuilder=null;builder.scope==='draft'?renderTemplateWizard():templateFieldsDialog();return;}
      const fieldMove=event.target.closest('[data-field-move]');if(fieldMove){const scope=fieldMove.dataset.fieldScope,index=Number(fieldMove.dataset.fieldIndex),target=index+(fieldMove.dataset.fieldMove==='up'?-1:1);syncFieldConfigInputs(fieldMove.closest('.template-wizard,form'),scope);const fields=scope==='draft'?state.uploadDraft?.fields:selectedTemplate()?.fields;if(fields&&moveField(fields,index,target)){scope==='draft'?renderTemplateWizard():templateFieldsDialog();}return;}
