      if(event.target.closest('[data-template-delete]')){const template=selectedTemplate();if(template)await deleteTemplate(template);return;}
      const fieldDelete=event.target.closest('[data-field-delete]');if(fieldDelete){const template=selectedTemplate();if(template)await deleteCustomField(template,fieldDelete.dataset.fieldDelete);return;}
      if(event.target.closest('[data-template-fields]'))return templateFieldsDialog();
      if(event.target.closest('[data-template-download]')){const record=await getTemplateFile(selectedTemplate().id);if(record)download(record.name,record.file);return;}
      if(event.target.closest('[data-template-scan]')){try{const result=await scanTemplate(state.uploadDraft.file);state.uploadDraft.fields=result.fields.map(field=>({...field,page:1}));state.uploadDraft.format=result.format;state.uploadDraft.ignoredFormulaCount=result.ignoredFormulaCount||0;state.uploadDraft.step=2;renderTemplateWizard();}catch(error){alert(error.message);}return;}
