      if(event.target.closest('[data-custom-add]')){const dialog=event.target.closest('dialog'),fieldKey=slug(dialog.querySelector('[data-custom-key]').value),label=dialog.querySelector('[data-custom-label]').value.trim(),type=dialog.querySelector('[data-custom-type]')?.value||'text';if(!fieldKey||!label)return alert('กรุณาระบุ Field key และชื่อที่แสดง');if(state.uploadDraft.fields.some(f=>f.key===fieldKey))return alert('Field key นี้มีอยู่แล้ว');syncFieldConfigInputs(dialog,'draft');state.uploadDraft.fields.push({key:fieldKey,label,type,required:false,source:'custom',occurrences:0,page:1,formula:''});if(type==='formula')state.formulaBuilder={scope:'draft',key:fieldKey,expression:''};renderTemplateWizard();return;}
      const draftFieldDelete=event.target.closest('[data-draft-field-delete]');if(draftFieldDelete){syncFieldConfigInputs(draftFieldDelete.closest('.template-wizard'),'draft');state.uploadDraft.fields.splice(Number(draftFieldDelete.dataset.draftFieldDelete),1);renderTemplateWizard();return;}
      const groupEdit=event.target.closest('[data-group-edit]');if(groupEdit){const group=state.data.groups.find(item=>item.id===groupEdit.dataset.groupEdit);if(group)return groupEditDialog(group);}
      const clearEntities=event.target.closest('[data-entity-selection-clear]');if(clearEntities){state.selectedEntities[clearEntities.dataset.entitySelectionClear].clear();render();return;}
      const deleteEntities=event.target.closest('[data-entity-delete-selected]');if(deleteEntities)return deleteSelectedEntities(deleteEntities.dataset.entityDeleteSelected);
